import{_ as l,o,c as t,a2 as r}from"./chunks/framework.Cs11k9ph.js";const g=JSON.parse('{"title":"✨ 功能特性（v3.2）","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1788072143000}'),e={name:"features.md"};function i(s,a,n,d,h,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="✨-功能特性-v3-2" tabindex="-1">✨ 功能特性（v3.2） <a class="header-anchor" href="#✨-功能特性-v3-2" aria-label="Permalink to &quot;✨ 功能特性（v3.2）&quot;">​</a></h1><blockquote><p>本文档对应 <strong>AgoraIn v3.2</strong>（AgoraInPro）。历史版本：v2.8 已归档（<a href="/v2.8/features.html">v2.8 功能特性</a>），v2.7 已归档（<a href="/v2.7/features.html">v2.7 功能特性</a>。</p></blockquote><p>AgoraIn v3.2 在一个窗口内提供<strong>大屏模式</strong>与<strong>控制模式</strong>两种工作模式，配套集控服务器与移动端 App。</p><hr><h2 id="大屏模式-打卡" tabindex="-1">大屏模式（打卡） <a class="header-anchor" href="#大屏模式-打卡" aria-label="Permalink to &quot;大屏模式（打卡）&quot;">​</a></h2><h3 id="任务管理" tabindex="-1">任务管理 <a class="header-anchor" href="#任务管理" aria-label="Permalink to &quot;任务管理&quot;">​</a></h3><ul><li>左侧<strong>任务树</strong>：文件夹 / 任务两级结构，支持<strong>打开、属性、重命名、删除</strong>（右键菜单），选中项浅蓝高亮</li><li>右侧<strong>多标签栏</strong>：每个任务一个标签页，支持<strong>新建（+）、切换、关闭</strong>；双击标签可重命名</li><li>工作区状态持久化：标签页列表与活动标签自动保存到 <code>workspace.json</code>，下次启动自动恢复</li></ul><h3 id="打卡面板" tabindex="-1">打卡面板 <a class="header-anchor" href="#打卡面板" aria-label="Permalink to &quot;打卡面板&quot;">​</a></h3><ul><li>学生<strong>按钮网格</strong>：行列数可配置（默认 6×6），每个学生一个圆角按钮，点击打卡</li><li>已打卡学生按钮变蓝（<code>#4285f4</code>），未打卡为浅灰；鼠标悬停半透明反馈</li><li><strong>右键取消打卡</strong>（已打卡学生），支持批量操作（任务树右键&quot;清空打卡记录&quot;）</li><li>网格自动按 <code>ButtonRows × ButtonCols</code> 布局，超出滚动</li></ul><h3 id="打卡排名" tabindex="-1">打卡排名 <a class="header-anchor" href="#打卡排名" aria-label="Permalink to &quot;打卡排名&quot;">​</a></h3><ul><li>左侧 320px 排名卡实时展示<strong>最早打卡</strong>的学生，按打卡时间排序</li><li>第 1/2/3 名分别<strong>金 / 银 / 铜</strong>高亮，展示打卡时间</li></ul><h3 id="在线模式与同步" tabindex="-1">在线模式与同步 <a class="header-anchor" href="#在线模式与同步" aria-label="Permalink to &quot;在线模式与同步&quot;">​</a></h3><ul><li>连接集控服务器后实时同步打卡数据，顶栏状态行显示服务器在线/离线指示灯（绿 <code>#34a853</code> / 红 <code>#ea4335</code>）</li><li>服务端可推送配置变更（配置版本追踪，自动应用）；集控平台发现新版本时自动弹窗提示管理员</li><li>支持从服务器加载数据、检查服务器状态</li></ul><h3 id="签到任务-二维码签到" tabindex="-1">签到任务（二维码签到） <a class="header-anchor" href="#签到任务-二维码签到" aria-label="Permalink to &quot;签到任务（二维码签到）&quot;">​</a></h3><ul><li>一键<strong>创建签到</strong>：生成带短码的签到链接与二维码，支持设置<strong>签到密码、教室、科目</strong></li><li>学生扫码后自动打卡，结果回写服务器，短码唯一索引防冲突</li></ul><h3 id="窗口体验" tabindex="-1">窗口体验 <a class="header-anchor" href="#窗口体验" aria-label="Permalink to &quot;窗口体验&quot;">​</a></h3><ul><li>无边框圆角窗口（DWM API），支持拖拽、最小化 / 最大化 / 关闭</li><li>白色半透明模式下拉框、现代化圆角右键菜单、SVG 圆形应用图标</li></ul><hr><h2 id="控制模式-控制中心" tabindex="-1">控制模式（控制中心） <a class="header-anchor" href="#控制模式-控制中心" aria-label="Permalink to &quot;控制模式（控制中心）&quot;">​</a></h2><h3 id="统计条" tabindex="-1">统计条 <a class="header-anchor" href="#统计条" aria-label="Permalink to &quot;统计条&quot;">​</a></h3><p>顶栏统计条：<strong>总设备数量 / 总任务数量 / 在线设备数量</strong>（蓝色大数值）</p><h3 id="左侧导航" tabindex="-1">左侧导航 <a class="header-anchor" href="#左侧导航" aria-label="Permalink to &quot;左侧导航&quot;">​</a></h3><p><strong>划课 / 设备列表 / 任务中心 / 集控平台列表</strong>，选中项浅蓝高亮</p><h3 id="划课-课时划消与排课" tabindex="-1">划课（课时划消与排课） <a class="header-anchor" href="#划课-课时划消与排课" aria-label="Permalink to &quot;划课（课时划消与排课）&quot;">​</a></h3><ul><li>学生列表管理：添加 / 删除学生，支持设置初始课时数；剩余课时以蓝色徽章展示</li><li>课时划消：输入课时数，<strong>划消课时</strong>（扣减）或<strong>增加课时</strong>（赠送），可填备注</li><li>课时记录流水：红扣（-X）绿增（+X），按学生筛选查看</li><li>月历排课：42 格月历（6 周 × 7 天），今日格带 <strong>&quot;今&quot; 徽章</strong>，选中日期蓝框高亮</li><li>排课规则：<strong>上课 / 下课时间必填</strong>（HH:mm，下课不得等于上课，支持跨天如 23:00–01:00），重复排课自动拦截</li><li>不排课日：周末默认提示，可将任意日期<strong>设为不排课日 / 恢复</strong>（自动清空当日排课，粉底&quot;休&quot;标记）</li><li><strong>复制排课</strong>：把某日排课复制到多个日期，可跳过不排课日</li><li><strong>自动扣减课时</strong>：开启后每 30 秒检查一次，课程结束后按 <code>实际时长 × 每小时课时消耗</code> 自动扣减学生课时（SlotKey 幂等去重，多实例安全）</li><li>设置项：<strong>每小时课时消耗</strong>（支持小数，如 0.5 / 1 / 1.5，范围 0–24）、<strong>自动划消开关</strong></li></ul><h3 id="集控平台列表" tabindex="-1">集控平台列表 <a class="header-anchor" href="#集控平台列表" aria-label="Permalink to &quot;集控平台列表&quot;">​</a></h3><ul><li>打开远程打卡服务器控制台（<code>ServerControlWindow</code>）：登录、仪表盘、设备、任务、考勤、用户管理</li><li>查看服务器状态、版本信息，管理员密码通过 SHA256 哈希校验</li></ul><hr><h2 id="集控服务器-server" tabindex="-1">集控服务器（Server） <a class="header-anchor" href="#集控服务器-server" aria-label="Permalink to &quot;集控服务器（Server）&quot;">​</a></h2><ul><li>ASP.NET + EF Core + <strong>SQLite</strong> 存储，默认监听端口 <strong>5250</strong>（<code>config.json</code> 可改）</li><li>设备注册与管理、打卡数据同步（<code>/api/sync_data</code>、<code>/api/load_data</code>）、考勤记录</li><li><strong>Web 管理面板</strong>：多用户登录、加盐 SHA256 密码哈希、权限管理（用户增删改、改密码、设备分配）</li><li><strong>签到任务</strong>：创建签到、短码生成、签到结果回写、按设备关联</li><li><strong>移动端 API</strong>：JWT 令牌认证、二维码签到、管理员仪表盘</li><li><strong>呼叫通知</strong>：<code>/api/mobile/calls</code> 发送呼叫，设备端 <code>/api/calls_pull</code> 拉取、<code>/api/calls_ack</code> 确认；三种类型（待下课/应急/传唤），自动过期标记</li><li>安全特性：未配置 <code>ServerPassword</code> 时自动生成随机密码并回写 <code>config.json</code>；<code>DebugMode</code> 调试开关；旧版明文密钥自动迁移为加密存储</li></ul><hr><h2 id="移动端-client-mobile-maui" tabindex="-1">移动端（Client.Mobile，MAUI） <a class="header-anchor" href="#移动端-client-mobile-maui" aria-label="Permalink to &quot;移动端（Client.Mobile，MAUI）&quot;">​</a></h2><h3 id="学生端" tabindex="-1">学生端 <a class="header-anchor" href="#学生端" aria-label="Permalink to &quot;学生端&quot;">​</a></h3><p>登录、任务列表 / 详情、<strong>扫码签到</strong>、二维码生成、历史记录、考勤详情</p><h3 id="管理员端" tabindex="-1">管理员端 <a class="header-anchor" href="#管理员端" aria-label="Permalink to &quot;管理员端&quot;">​</a></h3><p>登录、仪表盘、任务管理、用户管理、设置、学生网格、创建签到</p><hr><h2 id="classisland-联动插件-agorain-classislandplugin" tabindex="-1">ClassIsland 联动插件（AgoraIn.ClassIslandPlugin） <a class="header-anchor" href="#classisland-联动插件-agorain-classislandplugin" aria-label="Permalink to &quot;ClassIsland 联动插件（AgoraIn.ClassIslandPlugin）&quot;">​</a></h2><ul><li>运行于 <strong>ClassIsland 2.x</strong> 主程序进程内（<code>ClassIsland.Plugin.cipx</code> 安装包，2.1.1.0）</li><li>定时轮询集控平台（默认 10 秒，可配置），拉取本机待处理呼叫</li><li><strong>待下课时段通知</strong>：缓存并结合 ClassIsland 课表，在&quot;距下课 ≤ 提前分钟数&quot;窗口自动提醒</li><li><strong>上课应急通知 / 下课传唤</strong>：立即弹出置顶窗口（红 / 橙主题色），并<strong>中文语音朗读</strong>（System.Speech，自动选择中文语音，同一呼叫不重复朗读）</li><li>自动探测本机 AgoraIn 大屏客户端配置（<code>Program Files</code> / 本地程序目录 / <code>AGORAIN_HOME</code>）</li><li>配置持久化到 ClassIsland 插件目录 <code>settings.json</code>（平台地址 / 密码 / 设备 UUID 必须与教师端发送目标一致）</li></ul><hr><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>技术</th></tr></thead><tbody><tr><td>桌面客户端</td><td>.NET 10 / WPF（<code>net10.0-windows</code>），AssemblyName <code>AgoraIn</code></td></tr><tr><td>服务器</td><td>ASP.NET Core + Entity Framework Core + SQLite</td></tr><tr><td>移动端</td><td>.NET MAUI（Android / iOS / Windows）</td></tr><tr><td>二维码</td><td>QRCoder（签到链接 / 二维码生成）</td></tr><tr><td>图标 / 界面</td><td>SVG 生成应用图标与界面示意图</td></tr><tr><td>窗口效果</td><td>DWM API 窗口圆角、半透明阴影、DropShadowEffect</td></tr><tr><td>数据文件</td><td>System.Text.Json 序列化（config.json / workspace.json / classhours.json）</td></tr></tbody></table><h2 id="版本历史" tabindex="-1">版本历史 <a class="header-anchor" href="#版本历史" aria-label="Permalink to &quot;版本历史&quot;">​</a></h2><h3 id="v3-2-当前" tabindex="-1">v3.2（当前） <a class="header-anchor" href="#v3-2-当前" aria-label="Permalink to &quot;v3.2（当前）&quot;">​</a></h3><p><strong>新增</strong></p><ul><li>控制模式（控制中心）：统计条、左侧导航、划课页、设备列表（呼叫面板）、任务中心、集控平台列表</li><li>呼叫通知：教师端批量/单台发送呼叫（待下课 / 应急 / 传唤），设备弹窗 + 语音朗读</li><li>ClassIsland 联动插件 2.1.1.0：轮询修复、中文语音朗读</li><li>平台配置持久化（platforms.json，密码 DPAPI 加密），重启自动重连</li></ul><h3 id="v2-8-34" tabindex="-1">v2.8.34 <a class="header-anchor" href="#v2-8-34" aria-label="Permalink to &quot;v2.8.34&quot;">​</a></h3><p><strong>新增</strong></p><ul><li>控制模式（控制中心）：统计条、左侧导航、划课页、集控平台列表</li><li>课时划消系统：学生管理、课时划消/增加 + 备注、课时记录流水（红扣绿增）</li><li>月历排课：上课/下课时间必填、今日&quot;今&quot;徽章、选中蓝框、跨天课程、重复排课拦截</li><li>不排课日（自动清空排课、周末默认提示）、复制排课（可跳过不排课日）</li><li>自动扣减课时：按实际时长 × 每小时课时消耗，SlotKey 幂等去重</li><li>大屏模式：任务树、多标签页、签到任务（二维码 + 短码 + 密码）、在线同步、右键取消打卡</li></ul><p><strong>UI/体验</strong></p><ul><li>模式切换下拉框（白色半透明样式）</li><li>现代化圆角：输入框、选项卡、右键菜单、DWM 窗口圆角</li><li>SVG 圆形应用图标</li></ul><p><strong>修复</strong></p><ul><li>日历选中蓝框跟随日期</li><li>大屏模式取消打卡失效</li><li>控制模式显示错误模式名</li><li>白字继承链问题（下拉框/菜单文字颜色）</li></ul>',53)])])}const b=l(e,[["render",i]]);export{g as __pageData,b as default};
